from concurrent.futures import ThreadPoolExecutor

import pytest


def square(x: int) -> int:
    return x * x


def sum_squares(xs: list[int], workers: int = 4) -> int:
    """Return the sum of x * x over every element of xs.

    The squares are computed in parallel with a thread pool of `workers`
    threads, using `square`. Integer addition is exact and associative, so
    the result is identical for every worker count and equals the serial sum.
    An empty list gives 0. The input list is not modified.

    Raises ValueError if workers < 1.
    """
    if workers < 1:
        raise ValueError("workers must be >= 1")
    if not xs:
        return 0
    with ThreadPoolExecutor(max_workers=workers) as pool:
        return sum(pool.map(square, xs))


def test_basic() -> None:
    assert sum_squares([1, 2, 3]) == 14


def test_empty() -> None:
    assert sum_squares([]) == 0


def test_single() -> None:
    assert sum_squares([-7]) == 49


def test_negatives_and_zero() -> None:
    assert sum_squares([-3, 0, 3]) == 18


def test_large_ints_exact() -> None:
    big = 10**30
    assert sum_squares([big, -big, 1]) == 2 * big * big + 1


def test_same_result_at_every_worker_count() -> None:
    xs = list(range(-50, 51)) * 3
    expected = sum(square(x) for x in xs)
    for w in (1, 2, 3, 4, 8, 16, 101, 500):
        assert sum_squares(xs, workers=w) == expected


def test_more_workers_than_items() -> None:
    assert sum_squares([2, 3], workers=64) == 13
    assert sum_squares([], workers=64) == 0


def test_default_matches_explicit_workers() -> None:
    xs = [5, -4, 9, 1]
    assert sum_squares(xs) == sum_squares(xs, workers=1)


def test_input_not_modified() -> None:
    xs = [3, -1, 2]
    snapshot = list(xs)
    sum_squares(xs, workers=3)
    assert xs == snapshot


def test_invalid_workers() -> None:
    with pytest.raises(ValueError):
        sum_squares([1, 2], workers=0)
    with pytest.raises(ValueError):
        sum_squares([1, 2], workers=-2)


def test_large_input_matches_serial() -> None:
    xs = [(i * 7919) % 1001 - 500 for i in range(5000)]
    expected = sum(x * x for x in xs)
    with ThreadPoolExecutor(max_workers=2) as _:
        pass
    assert sum_squares(xs, workers=8) == expected
